<span class="line"><span style="color:#ABB2BF;">trans </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> transforms.</span><span style="color:#61AFEF;">ToTensor</span><span style="color:#ABB2BF;">()</span></span>
